tools.example:
// 2D TE-type waveguide model driven at 10 GHz with a user-set mesh size
model.component("comp1").physics().create("emw", "ElectromagneticWaves", "geom1");
model.component("comp1").physics("emw").prop("components").set("components", "outofplane");
model.component("comp1").physics("emw").prop("MeshControl").set("SizeControlParameter", "UserDefined");
model.component("comp1").physics("emw").prop("MeshControl").set("PhysicsControlledMeshMaximumElementSize", "lda0/5");
// Application Library: RF_Module/Antennas/conical_antenna (2D axisymmetric, in-plane components)

model.component("comp1").physics("ewfd").feature("wee1").set("DisplacementFieldModel", "RefractiveIndex");
model.component("comp1").physics("ewfd").feature("wee1").set("n_mat", "userdef");
model.component("comp1").physics("ewfd").feature("wee1").set("n", new String[]{"2.21", "0", "0", "0", "2.21", "0", "0", "0", "2.14"});
// uniaxial crystal; Application Library: Wave_Optics_Module/Verification_Examples/optically_anisotropic_waveguide

model.component("comp1").physics("emw").feature("wee1").set("DisplacementFieldModel", "LossTangentDF");
model.component("comp1").physics("emw").feature("wee1").set("tanDelta_mat", "userdef");
model.component("comp1").physics("emw").feature("wee1").set("tanDelta", "0.0002");
// Application Libraries: RF_Module/Transmission_Lines_and_Waveguides/microstrip_line_tem_via (LossTangentDF), RF_Module/Microwave_Heating/rf_heating (LossTangent)

model.component("comp1").physics("ewfd").feature("wee1").set("DisplacementFieldModel", "DrudeLorentzDispersionModel");
model.component("comp1").physics("ewfd").feature("wee1").set("omegap", "omega_p");
// then fill the oscillator table (f, omega0, Gamma) in the GUI; for the time-domain counterpart see RF_Module/Tutorials/drude_lorentz_media

model.component("comp1").physics("emw").create("ecd1", "ExternalCurrentDensity", 2);
model.component("comp1").physics("emw").feature("ecd1").selection().set(new int[]{3});
// 2D (out-of-plane) model: set Je = (0, 0, 1e6[A/m^2]) in the settings of ecd1 to drive a line-source-like conductor

model.component("comp1").physics("emw").create("ffi1", "FarFieldDomainInhomogeneous", 3);
model.component("comp1").physics("emw").feature("ffi1").feature("sub1").selection().set(new int[]{1, 2});
// Application Libraries: RF_Module/Scattering_and_RCS/embedded_scatterer_on_substrate, Wave_Optics_Module/Optical_Scattering/scatterer_on_substrate

model.component("comp1").physics("emw").create("ps1", "PeriodicStructure", 3);
model.component("comp1").physics("emw").feature("ps1").set("LinearPol", "TM");
model.component("comp1").physics("emw").feature("ps1").set("alpha1_inc", "theta");
model.component("comp1").physics("emw").feature("ps1").runCommand("addDiffractionOrders");
// Application Libraries: RF_Module/EMI_EMC_Applications/frequency_selective_surface_csrr, RF_Module/Tutorials/hexagonal_grating, Wave_Optics_Module/Applications/plasmonic_wire_grating

model.component("comp1").physics("ewfd").create("pc1", "PeriodicCondition", 1);
model.component("comp1").physics("ewfd").feature("pc1").set("PeriodicType", "Floquet");
model.component("comp1").physics("ewfd").feature("pc1").set("kFloquet", new String[]{"k_x", "0", "0"});
// photonic-crystal band diagram with an Eigenfrequency sweep over k_x: Wave_Optics_Module/Gratings_and_Metamaterials/bandgap_photonic_crystal

model.component("comp1").physics("emw").create("sar1", "SpecificAbsorptionRate", 3);
model.component("comp1").physics("emw").feature("sar1").selection().named("head_tissue");
// evaluate max(emw.SAR) and emw.SAR1g; Application Libraries: RF_Module/Microwave_Heating/sar_in_human_head, RF_Module/EMI_EMC_Applications/sar_wifi_antenna

model.component("comp1").physics("emw").create("pec2", "DomainPerfectElectricConductor", 3);
model.component("comp1").physics("emw").feature("pec2").selection().set(new int[]{4});
// Application Libraries: RF_Module/Scattering_and_RCS/embedded_scatterer_on_substrate (domain PEC), RF_Module/Antennas/dipole_antenna (domain IBC)

model.component("comp1").physics("emw").create("efb1", "ElectricField", 2);
model.component("comp1").physics("emw").feature("efb1").selection().set(new int[]{12});
// set E0 = (0, 0, E_in*exp(-(x/w)^2)) to impose a known aperture field

model.component("comp1").physics("emw").create("mfb1", "MagneticFieldBoundary", 2);
model.component("comp1").physics("emw").feature("mfb1").selection().set(new int[]{1});
// H0 = (0, H_s, 0) on the outer wall of a cavity validation model

model.component("comp1").physics("ewfd").create("mbc1", "MatchedBoundaryCondition", 1);
model.component("comp1").physics("ewfd").feature("mbc1").set("IncidentField", "GaussianBeam");
model.component("comp1").physics("ewfd").feature("mbc1").set("w0", "w0");
// Application Library: Wave_Optics_Module/Beam_Propagation/gaussian_beam_propagation_optical_prism

model.component("comp1").physics("ewfd").feature("mbc1").create("rpnt1", "ReferencePoint", 0);
model.component("comp1").physics("ewfd").feature("mbc1").feature("rpnt1").selection().set(new int[]{3});
// beam axis passes through point 3: Application Library Wave_Optics_Module/Beam_Propagation/gaussian_beam_propagation_optical_prism

model.component("comp1").physics("emw").create("smcd1", "SurfaceMagneticCurrentDensity", 2);
model.component("comp1").physics("emw").feature("smcd1").selection().set(new int[]{9});
// annular aperture source for a monopole; compare the Magnetic Current (edge) approach in RF_Module/Antennas/magnetic_frill

model.component("comp1").physics("ewfd").create("libc1", "LayeredImpedanceBoundaryCondition", 1);
model.component("comp1").physics("ewfd").feature("libc1").set("substrateMaterial", "mat2");
// Application Library: Wave_Optics_Module/Couplers_Filters_and_Mirrors/enhanced_mems_mirror_coating

model.component("comp1").physics("emw").create("symp1", "SymmetryPlane", 2);
model.component("comp1").physics("emw").feature("symp1").set("Symmetry_type", "pmc");
model.component("comp1").physics("emw").feature("symp1").selection().set(new int[]{2});
// Application Libraries: RF_Module/Microwave_Heating/microwave_oven, RF_Module/Verification_Examples/rcs_sphere

model.component("comp1").physics("emw").create("mc1", "MagneticCurrent", 0);
model.component("comp1").physics("emw").feature("mc1").selection().set(new int[]{5});
// 2D axisymmetric monopole fed by a magnetic frill: Application Library RF_Module/Antennas/magnetic_frill

model.component("comp1").physics("temw").create("edc1", "EdgeCurrent", 1);
model.component("comp1").physics("temw").feature("edc1").set("CurrentPulseType", "Lightning");
model.component("comp1").physics("temw").feature("edc1").set("v_p", "c_const/3");
// Application Libraries: RF_Module/ESD_and_Lightning_Surge/lightning_induced_voltage_airplane, lightning_induced_voltage_overhead_lines

model.component("comp1").physics("ewfd").create("epd1", "ElectricPointDipole", 0);
model.component("comp1").physics("ewfd").feature("epd1").selection().set(new int[]{7});
// Application Library: Wave_Optics_Module/Gratings_and_Metamaterials/dipole_near_hyperbolic_metamaterial

model.component("comp1").physics("emw").create("mpd1", "MagneticPointDipole", 0);
model.component("comp1").physics("emw").feature("mpd1").selection().set(new int[]{11});
// loop-probe excitation of a dielectric resonator, then evaluate emw.normEfar

model.component("comp1").physics("emw").create("lco1", "LineCurrentOutOfPlane", 0);
model.component("comp1").physics("emw").feature("lco1").selection().set(new int[]{4});
// 2D photonic crystal waveguide excited by a line source; solve with components = outofplane

model.component("comp1").physics("ewfd").prop("BackgroundField").set("SolveFor", "scatteredField");
model.component("comp1").physics("ewfd").prop("BackgroundField").set("WaveType", "GaussianBeam");
model.component("comp1").physics("ewfd").prop("BackgroundField").set("GaussianBeamType", "PlaneWaves");
model.component("comp1").physics("ewfd").prop("BackgroundField").set("WaveVectorDistributionType", "userdef");
model.component("comp1").physics("ewfd").prop("BackgroundField").set("ktMax", "1.5*ewfd.k0");
// Application Libraries: Wave_Optics_Module/Optical_Scattering/nanorods; RF_Module/Scattering_and_RCS/cylinder_graphene_cloak (2D-axi plane wave)
